const input = $json.body ?? $json;

const text = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const toBoolean = (value) => {
  if (typeof value === 'boolean') return value;
  return ['true', '1', 'yes', 'on'].includes(text(value).toLowerCase());
};

const clinic_name = text(input.clinic_name);
const window_start_hours = Number(input.window_start_hours ?? 20);
const window_end_hours = Number(input.window_end_hours ?? 28);
const response_deadline_hours = Number(input.response_deadline_hours ?? 12);
const channel = text(input.channel || 'whatsapp').toLowerCase();
const limit = Number(input.limit ?? 100);
const confirm_generation = toBoolean(input.confirm_generation);

const errors = [];

if (!clinic_name) {
  errors.push({
    field: 'clinic_name',
    message: 'نام کلینیک الزامی است.',
  });
}

if (
  !Number.isInteger(window_start_hours) ||
  window_start_hours < 0 ||
  window_start_hours > 720
) {
  errors.push({
    field: 'window_start_hours',
    message: 'window_start_hours باید یک عدد صحیح بین 0 و 720 باشد.',
  });
}

if (
  !Number.isInteger(window_end_hours) ||
  window_end_hours < 1 ||
  window_end_hours > 720 ||
  window_end_hours <= window_start_hours
) {
  errors.push({
    field: 'window_end_hours',
    message: 'window_end_hours باید از window_start_hours بزرگ‌تر و حداکثر 720 باشد.',
  });
}

if (
  !Number.isInteger(response_deadline_hours) ||
  response_deadline_hours < 1 ||
  response_deadline_hours > 168
) {
  errors.push({
    field: 'response_deadline_hours',
    message: 'response_deadline_hours باید یک عدد صحیح بین 1 و 168 باشد.',
  });
}

if (
  !['whatsapp', 'sms', 'phone', 'telegram', 'web', 'manual'].includes(channel)
) {
  errors.push({
    field: 'channel',
    message: 'کانال انتخاب‌شده معتبر نیست.',
  });
}

if (!Number.isInteger(limit) || limit < 1 || limit > 500) {
  errors.push({
    field: 'limit',
    message: 'limit باید یک عدد صحیح بین 1 و 500 باشد.',
  });
}

if (confirm_generation !== true) {
  errors.push({
    field: 'confirm_generation',
    message: 'ایجاد درخواست‌های تأیید باید به‌صورت صریح تأیید شود.',
  });
}

return [
  {
    json: {
      clinic_name,
      window_start_hours,
      window_end_hours,
      response_deadline_hours,
      channel,
      limit,
      confirm_generation,
      validation_status: errors.length === 0 ? 'valid' : 'invalid',
      errors,
    },
  },
];

return [
  {
    json: {
      success: false,
      result: 'invalid_request',
      message: 'اطلاعات تولید درخواست‌های تأیید ناقص یا نامعتبر است.',
      confirmation_request_count: 0,
      confirmation_requests: [],
      errors: $json.errors ?? [],
    },
  },
];
